import { chromium, webkit } from 'playwright';
import fs from 'node:fs';

const BASE='http://127.0.0.1:4173/';
const OUT='/tmp/full-audit-evidence';
fs.rmSync(OUT,{recursive:true,force:true});fs.mkdirSync(OUT,{recursive:true});
const results={checks:[],errors:[],scans:{},cinematics:[],viewports:[],home:{},story:{},atlas:{},feedback:{},focus:{},audio:{},performance:{},webkit:[],externalRequired:['physical-phone touch/performance/battery','genuine iOS Safari hardware','exhaustive assistive-technology testing','subjective speaker/headphone audio mixing']};
function assert(c,m){if(!c)throw new Error(m)}
function check(name,detail='ok'){results.checks.push({name,detail});console.log('CHECK',name,typeof detail==='string'?detail:JSON.stringify(detail))}
function listen(page,label){page.on('pageerror',e=>results.errors.push(`${label} pageerror: ${String(e)}`));page.on('console',m=>{if(m.type()==='error')results.errors.push(`${label} console: ${m.text()}`)});page.on('requestfailed',r=>results.errors.push(`${label} requestfailed: ${r.url()} ${r.failure()?.errorText||''}`))}
async function shot(p,name){await p.screenshot({path:`${OUT}/${name}.png`,fullPage:false})}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const SEEN={opening:1,'across-drift':1,'old-maps':1,homeward:1};
function starsBefore(unlocked,{holes=[]}={}){const s={};for(let i=1;i<unlocked;i++)if(!holes.includes(i))s[i]=3;return s}
async function contextFor(browser,{viewport={width:390,height:844},unlocked=400,stars=starsBefore(unlocked),prefs={motion:'reduced',textSize:'normal'},seen=SEEN,music=true,sfx=true}={}){
 const ctx=await browser.newContext({viewport,deviceScaleFactor:1,reducedMotion:'no-preference'});
 await ctx.addInitScript(x=>{localStorage.setItem('latchlings_campaign400_progress_v1',JSON.stringify({unlocked:x.unlocked,stars:x.stars}));localStorage.setItem('latchlings_cinematics_seen_v1',JSON.stringify(x.seen));localStorage.setItem('latchlings_ui_prefs_v1',JSON.stringify(x.prefs));localStorage.setItem('latchlings_music_enabled_v1',String(x.music));localStorage.setItem('latchlings_sfx_enabled_v1',String(x.sfx));},{unlocked,stars,prefs,seen,music,sfx});
 return ctx;
}
async function gotoPage(ctx,label){const p=await ctx.newPage();listen(p,label);p.setDefaultTimeout(25000);await p.goto(BASE,{waitUntil:'networkidle'});return p}
async function settleGame(p,L,mode='campaign'){await p.evaluate(({L,mode})=>startLevel(L,mode),{L,mode});await p.waitForTimeout(35);await p.evaluate(()=>{try{window.LatchlingsStoryTheme?.close(false)}catch(_){};try{if(window.LatchlingsCinematics?.active)window.LatchlingsCinematics.finish(true)}catch(_){};window.LatchlingsStoryRail?.render()});await p.waitForTimeout(35)}
async function basicBounds(p,label,{mustFitHeight=false}={}){const x=await p.evaluate(()=>{const vis=[...document.querySelectorAll('button')].filter(e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0&&!e.disabled});return {w:innerWidth,h:innerHeight,doc:document.documentElement.scrollWidth,body:document.body.scrollWidth,minTarget:vis.length?Math.min(...vis.map(e=>Math.min(e.getBoundingClientRect().width,e.getBoundingClientRect().height))):0,screen:document.body.dataset.screen||document.querySelector('.screen.active')?.id||''}});assert(x.doc<=x.w+1&&x.body<=x.w+1,`${label}: horizontal overflow ${JSON.stringify(x)}`);if(x.minTarget)assert(x.minTarget>=37,`${label}: unexpected tiny visible button ${JSON.stringify(x)}`);check(label,x);return x}

const chromiumBrowser=await chromium.launch({headless:true});

// Protect the R1-R5 acceptance while adding the broader audit work.
async function scanAllBoards(viewport,textSize){const ctx=await contextFor(chromiumBrowser,{viewport,prefs:{motion:'reduced',textSize}});const p=await gotoPage(ctx,`boards-${viewport.width}-${textSize}`);await p.evaluate(s=>window.LatchlingsPrefs.set('textSize',s),textSize);const out=await p.evaluate(async()=>{const fails=[],samples=[],movementRails=[];for(let L=1;L<=400;L++){startLevel(L,'campaign');await new Promise(r=>setTimeout(r,0));try{window.LatchlingsStoryTheme?.close(false)}catch(_){};try{if(window.LatchlingsCinematics?.active)window.LatchlingsCinematics.finish(true)}catch(_){};window.LatchlingsStoryRail?.render();const rail=document.querySelector('.story-level-rail'),story=document.querySelector('.story-rail-main p'),tip=document.querySelector('.mechanic-chip-copy'),controls=document.querySelector('.controls'),selected=document.querySelectorAll('.latchling.selected'),cr=controls?.getBoundingClientRect(),sr=story?.getBoundingClientRect(),rr=rail?.getBoundingClientRect(),tr=tip?.getBoundingClientRect(),why=[];if(!rail||!story||!tip)why.push('missing rail/story/tip');if(story&&story.scrollHeight>story.clientHeight+1)why.push('story clip');if(tip&&tip.scrollHeight>tip.clientHeight+1)why.push('tip clip');if(sr&&rr&&sr.bottom>rr.bottom+1)why.push(`story below rail ${sr.bottom}/${rr.bottom}`);if(tr&&tr.right>innerWidth+1)why.push('tip horizontal overflow');if(cr&&cr.bottom>innerHeight+1)why.push(`controls below viewport ${cr.bottom}/${innerHeight}`);if(document.documentElement.scrollWidth>innerWidth+1||document.body.scrollWidth>innerWidth+1)why.push('horizontal overflow');if(selected.length!==1)why.push(`selected count ${selected.length}`);const ts=tip&&getComputedStyle(tip);if(ts&&(ts.overflow==='hidden'||ts.textOverflow==='ellipsis'||(ts.webkitLineClamp&&ts.webkitLineClamp!=='none')))why.push('tip clipping css');const targets=[...document.querySelectorAll('.controls button')].filter(e=>getComputedStyle(e).display!=='none').map(e=>Math.min(e.getBoundingClientRect().width,e.getBoundingClientRect().height));if(targets.length&&Math.min(...targets)<44)why.push(`game target ${Math.min(...targets)}`);if(why.length)fails.push({L,why});if([1,50,100,150,200,250,300,350,400].includes(L))samples.push({L,story:getComputedStyle(story).fontSize,tip:getComputedStyle(tip).fontSize,controlsBottom:cr?.bottom,railH:rr?.height});if((L-1)%10===0)movementRails.push({L,text:story.textContent.trim(),range:document.getElementById('board')?.dataset.boardRange})}return {fails,samples,movementRails}});assert(out.fails.length===0,`all-board ${viewport.width}x${viewport.height} ${textSize}: ${JSON.stringify(out.fails.slice(0,25))}`);assert(new Set(out.movementRails.map(x=>x.text)).size>=35,`movement rails insufficiently distinct ${new Set(out.movementRails.map(x=>x.text)).size}`);results.scans[`${viewport.width}x${viewport.height}-${textSize}`]=out;check(`all 400 boards ${viewport.width}x${viewport.height} ${textSize}`,out.samples);await ctx.close();return out}
const b390n=await scanAllBoards({width:390,height:844},'normal');const b390l=await scanAllBoards({width:390,height:844},'large');const b320n=await scanAllBoards({width:320,height:568},'normal');const b320l=await scanAllBoards({width:320,height:568},'large');
for(const L of [1,50,100,150,200,250,300,350,400]){const n=b390n.samples.find(x=>x.L===L),g=b390l.samples.find(x=>x.L===L);assert(parseFloat(g.story)>parseFloat(n.story),`large story font not larger L${L}`);assert(parseFloat(g.tip)>parseFloat(n.tip),`large tip font not larger L${L}`)}check('R1-R4 regression protected','400 boards at 390/320 Normal+Large');

// Forty movement beginnings: Story Card and rail content must exist, fit, and evolve by the end of the movement.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844}});const p=await gotoPage(ctx,'movements');const rows=[];
 for(let L=1;L<=391;L+=10){await settleGame(p,L);await p.evaluate(L=>window.LatchlingsStoryTheme.show(L,true),L);await p.waitForTimeout(15);const a=await p.evaluate(()=>{const panel=document.getElementById('storyCardPanel'),title=document.getElementById('storyCardTitle'),context=document.getElementById('storyCardContext'),obj=document.getElementById('storyCardObjective'),r=panel.getBoundingClientRect();return {title:title.textContent.trim(),context:context.textContent.trim(),objective:obj.textContent.trim(),fit:r.top>=0&&r.bottom<=innerHeight+1,overflow:panel.scrollWidth<=panel.clientWidth+1}});assert(a.title&&a.context&&a.objective,`movement ${L} missing story card substance`);assert(a.fit&&a.overflow,`movement ${L} story card geometry ${JSON.stringify(a)}`);await p.evaluate(()=>window.LatchlingsStoryTheme.close(false));const end=Math.min(400,L+9);await settleGame(p,end);const endText=await p.locator('.story-rail-main p').innerText();await settleGame(p,L);const startText=await p.locator('.story-rail-main p').innerText();assert(startText!==endText,`movement ${L}-${end} rail did not evolve`);rows.push({L,title:a.title,startText,endText})}
 assert(rows.length===40,'expected 40 movement starts');results.story.movements=rows;check('40 movement beginnings and evolving rail conclusions',`count=${rows.length}`);await ctx.close();
}

// All 25 cinematics: unique directed evidence, ordered dialogue, fixed navigation, actionable opening, reduced-motion safety.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:320,height:568},prefs:{motion:'reduced',textSize:'normal'}});const p=await gotoPage(ctx,'cinematics');const directed=new Set(['opening-delivery','opening-chores','opening-misses','opening-flex','opening-call','opening-neighbors','opening-demo','opening-level1','prism-horizon','porch','drift-endpoints','alignment-mismatch','porch-route-payoff','drawer-discovery','dated-landmarks','map-time-sequence','tended-to-automated','living-vs-frozen','copper-route-payoff','community-signals','people-tasks','response-chain','routes-in-time','crown-meeting','ordinary-home-pullback']);let count=0;
 for(const id of ['opening','across-drift','old-maps','homeward']){await p.evaluate(id=>window.LatchlingsCinematics.show(id,{markSeen:false}),id);await p.waitForTimeout(120);const beats=await p.evaluate(id=>window.LatchlingsCinematics.CINEMATICS[id].beats.length,id);for(let i=0;i<beats;i++){await p.waitForTimeout(80);const x=await p.evaluate(()=>{const api=window.LatchlingsCinematics,beat=api.CINEMATICS[api.active].beats[api.beat],stage=document.getElementById('cinematicStage'),copy=document.querySelector('.cinematic-copy'),footer=document.querySelector('.cinematic-footer'),next=document.getElementById('cinematicNext'),skip=document.getElementById('cinematicSkip'),rect=e=>{const r=e.getBoundingClientRect();return {t:r.top,b:r.bottom,l:r.left,r:r.right,w:r.width,h:r.height}};return {id:api.active,i:api.beat+1,visual:beat.visual,label:stage.getAttribute('aria-label'),sourceSpeakers:beat.lines.filter(x=>x[0]!=='Narrator').map(x=>x[0]),domSpeakers:[...document.querySelectorAll('.cin-opening-dialogue-row')].map(x=>x.dataset.speaker),footer:rect(footer),copy:rect(copy),next:rect(next),skip:rect(skip),nextText:next.textContent.trim(),animations:[...stage.querySelectorAll('*')].filter(e=>getComputedStyle(e).animationName!=='none').length}});assert(directed.has(x.visual),`${id} beat ${i+1} generic visual ${x.visual}`);assert(x.label&&x.label.length>12,`${id} beat ${i+1} missing visual equivalent`);assert(JSON.stringify(x.domSpeakers)===JSON.stringify(x.sourceSpeakers),`${id} beat ${i+1} dialogue order ${JSON.stringify(x)}`);assert(x.next.b<=568+1&&x.skip.b<=568+1&&x.next.h>=44&&x.skip.h>=44,`${id} beat ${i+1} nav ${JSON.stringify(x)}`);assert(x.footer.t>=x.copy.b-1,`${id} beat ${i+1} footer overlap`);assert(x.animations===0,`${id} beat ${i+1} animates under reduced motion: ${x.animations}`);results.cinematics.push(x);count++;if((id==='opening'&&[1,2,3,7,8].includes(i+1))||(id==='across-drift'&&[3,5].includes(i+1))||(id==='old-maps'&&[1,4,6].includes(i+1))||(id==='homeward'&&[2,5,6].includes(i+1)))await shot(p,`cin-${id}-${i+1}`);if(i<beats-1)await p.click('#cinematicNext')};await p.evaluate(()=>window.LatchlingsCinematics.finish(true))}
 assert(count===25,`expected 25 beats got ${count}`);const actions=results.cinematics.filter(x=>x.id==='opening').map(x=>x.nextText);assert(actions[4]==='Answer the call'&&actions[6]==='Try the route'&&actions[7]==='Begin Level 1',`opening action labels ${JSON.stringify(actions)}`);check('all 25 cinematics directorially staged and phone-safe',`beats=${count}`);
 // Guided teaching interaction.
 await p.evaluate(()=>window.LatchlingsCinematics.show('opening',{markSeen:false}));for(let i=0;i<6;i++){await p.click('#cinematicNext');await p.waitForTimeout(45)}const demo=p.locator('.cin-demo-controls');assert(await demo.count()===1,'guided opening demo missing');await demo.locator('button[data-demo-step="1"]').click();assert((await demo.locator('.cin-demo-status').innerText()).includes('move right'),'demo step 1 failed');await demo.locator('button[data-demo-step="2"]').click();assert((await demo.locator('.cin-demo-status').innerText()).includes('Stopped'),'demo step 2 failed');await p.evaluate(()=>window.LatchlingsCinematics.finish(true));check('opening guided teaching interaction','2-step evidence');await ctx.close();
}

// Canonical ending at phone and landscape sizes.
for(const viewport of [{width:320,height:568},{width:844,height:390}]){
 const ctx=await contextFor(chromiumBrowser,{viewport,unlocked:400,stars:{...starsBefore(401),400:3}});const p=await gotoPage(ctx,`ending-${viewport.width}`);await p.evaluate(()=>screen('complete'));await p.waitForTimeout(300);const x=await p.evaluate(()=>{const f=document.getElementById('endingHomeFrame'),primary=document.getElementById('completeHome'),secondary=document.getElementById('completeLevels'),card=document.querySelector('.ending-resolution-card'),r=e=>{const b=e.getBoundingClientRect();return {t:b.top,b:b.bottom,l:b.left,r:b.right,w:b.width,h:b.height}};const d=f.contentDocument;return {oldEnding:document.querySelectorAll('.ending-island').length,primaryText:primary.textContent.trim(),secondaryText:secondary.textContent.trim(),primary:r(primary),secondary:r(secondary),card:r(card),doc:document.documentElement.scrollWidth,frameReady:!!d?.body?.classList.contains('ending-embed'),stage8:!!d?.querySelector('#c2 .phone.story-stage-8'),distant:d?getComputedStyle(d.querySelector('#c2 .story-distant-islands')).display:null,ordinary:[...document.querySelectorAll('.ending-ordinary-list span')].map(e=>e.textContent.trim()),thesis:document.querySelector('.ending-note')?.textContent.trim()}});assert(x.oldEnding===0,'duplicate old ending island remains');assert(x.primaryText==='Return to Little Home'&&x.frameReady&&x.stage8&&x.distant!=='none',`canonical ending missing ${JSON.stringify(x)}`);assert(x.ordinary.length===3&&/No master switch/.test(x.thesis),`ending ordinary/thesis missing ${JSON.stringify(x)}`);assert(x.doc<=viewport.width+1,`ending horizontal overflow ${JSON.stringify(x)}`);assert(x.primary.h>=44&&x.secondary.h>=44,`ending target small ${JSON.stringify(x)}`);if(viewport.height>=500)assert(x.card.b<=viewport.height+1,`ending card below phone ${JSON.stringify(x)}`);results.viewports.push({ending:viewport,...x});await shot(p,`ending-${viewport.width}x${viewport.height}`);check(`canonical ending ${viewport.width}x${viewport.height}`,x);await ctx.close();
}

// Little Home: contextual CTA, keepsake memory, purposeful resident activity, Reduced Motion regression.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844},unlocked:251,stars:starsBefore(251),prefs:{motion:'system',textSize:'normal'}});const p=await gotoPage(ctx,'home');const f=p.frameLocator('#homeTitleFrame');await f.locator('#c2 .play-main').waitFor();await p.waitForTimeout(300);const cta={main:await f.locator('#c2 .play-main').innerText(),context:await f.locator('#c2 .play-context').innerText()};assert(/Continue journey/.test(cta.main)&&/Level 251/.test(cta.context),`contextual CTA ${JSON.stringify(cta)}`);const mem=f.locator('#c2 [data-memory="mailbox"]');assert(await mem.getAttribute('role')==='button'&&await mem.getAttribute('tabindex')==='0','keepsake not interactive');await mem.click();await p.waitForTimeout(60);assert((await p.locator('#modal').innerText()).includes('Sunpetal mailbox'),'keepsake memory modal wrong');await p.click('#homeMemoryClose');
 await f.locator('#c2').evaluate(root=>{window.__auditHomeActions=[];new MutationObserver(()=>{if(root.dataset.homeAction)window.__auditHomeActions.push(root.dataset.homeAction)}).observe(root,{attributes:true,attributeFilter:['data-home-action']})});await p.waitForTimeout(12500);const seenActions=await f.locator('#c2').evaluate(()=>window.__auditHomeActions||[]);assert(seenActions.length>0,`no purposeful Home resident action observed ${JSON.stringify(seenActions)}`);results.home={cta,seenActions};await shot(p,'home-purposeful-action');
 await p.evaluate(()=>window.LatchlingsPrefs.set('motion','reduced'));const before=await f.locator('#c2 .resident.adult').evaluateAll(es=>es.map(e=>Number(e.dataset.moveCount||0)));await p.waitForTimeout(9000);const after=await f.locator('#c2 .resident.adult').evaluateAll(es=>es.map(e=>Number(e.dataset.moveCount||0)));assert(JSON.stringify(before)===JSON.stringify(after),'Reduced Motion resident regression');check('Little Home context, memories, chores, Reduced Motion',results.home);await ctx.close();
 const doneCtx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844},unlocked:400,stars:{...starsBefore(401),400:3}});const doneP=await gotoPage(doneCtx,'home-complete');const df=doneP.frameLocator('#homeTitleFrame');await df.locator('#c2 .play-main').waitFor();assert((await df.locator('#c2 .play-main').innerText()).includes('Return to the living Skyway'),'completed Home CTA wrong');await doneCtx.close();
}

// Journal hierarchy and characterization.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844},unlocked:321,stars:starsBefore(321)});const p=await gotoPage(ctx,'story');await p.evaluate(()=>openStoryScreen());await p.waitForTimeout(80);const initial=await p.evaluate(()=>({tabs:[...document.querySelectorAll('.story-section-tab')].map(b=>[b.textContent.trim(),b.getAttribute('aria-selected')]),visible:[...document.querySelectorAll('[data-story-panel]')].filter(x=>!x.hidden).map(x=>x.dataset.storyPanel),contrib:[...document.querySelectorAll('.story-person-contribution')].map(x=>x.textContent.trim())}));assert(initial.tabs.length===4&&JSON.stringify(initial.visible)==='["now"]',`journal hierarchy ${JSON.stringify(initial)}`);assert(initial.contrib.length===5&&initial.contrib.every(Boolean),'resident contributions missing');for(const sec of ['residents','journey','films']){await p.click(`[data-story-section="${sec}"]`);const vis=await p.evaluate(()=>[...document.querySelectorAll('[data-story-panel]')].filter(x=>!x.hidden).map(x=>x.dataset.storyPanel));assert(JSON.stringify(vis)===JSON.stringify([sec]),`journal ${sec} visibility ${JSON.stringify(vis)}`)}results.story.journal=initial;await shot(p,'story-residents');check('journal sections + authored resident contributions',initial);await ctx.close();
}

// Atlas hierarchy and state distinction.
{
 const stars=starsBefore(24,{holes:[22,23]});const ctx=await contextFor(chromiumBrowser,{viewport:{width:320,height:568},unlocked:24,stars});const p=await gotoPage(ctx,'atlas');await p.evaluate(()=>{screen('levels');chapterView=1;rangeView=2;renderChapter()});await p.waitForTimeout(80);const x=await p.evaluate(()=>{const tab=[...document.querySelectorAll('.atlas-waypoint-tab')].map(e=>({w:e.getBoundingClientRect().width,h:e.getBoundingClientRect().height,scroll:e.scrollWidth,client:e.clientWidth}));const region=[...document.querySelectorAll('.atlas-region-dot')].map(e=>({w:e.getBoundingClientRect().width,h:e.getBoundingClientRect().height}));const style=sel=>{const e=document.querySelector(sel),s=getComputedStyle(e.querySelector('.atlas-island'));return {cls:e.className,opacity:s.opacity,filter:s.filter,shadow:s.boxShadow,label:e.getAttribute('aria-label')}};return {tabs:tab,regions:region,done:style('.atlas-node.done'),available:style('.atlas-node:not(.done):not(.current):not(.locked)'),current:style('.atlas-node.current'),locked:style('.atlas-node.locked'),map:document.getElementById('levelGrid').getAttribute('aria-label'),overflow:document.documentElement.scrollWidth-innerWidth}});assert(x.tabs.every(t=>t.h>=44&&t.scroll<=t.client+2),`Atlas tab target/clip ${JSON.stringify(x.tabs)}`);assert(x.regions.every(t=>t.h>=44&&t.w>=44),`Atlas chapter targets ${JSON.stringify(x.regions)}`);assert(x.done.label!==x.available.label&&x.current.label!==x.locked.label,'Atlas semantic states missing');assert(JSON.stringify([x.done.filter,x.done.shadow])!==JSON.stringify([x.current.filter,x.current.shadow]),'Atlas visual states not distinct');assert(x.overflow<=1,`Atlas horizontal overflow ${x.overflow}`);results.atlas=x;await shot(p,'atlas-state-hierarchy-320');check('Atlas hierarchy, landmarks and state distinction',x);await ctx.close();
}

// Gameplay causality: blocked door, switch link, arrival acknowledgement, star criteria.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844},prefs:{motion:'reduced',textSize:'normal'}});const p=await gotoPage(ctx,'feedback');
 const doorCase=await p.evaluate(()=>{const dirs={U:[-1,0],D:[1,0],L:[0,-1],R:[0,1]};for(let L=1;L<=400;L++){const lev=LEVELS[L-1];for(let pi=0;pi<lev.pieces.length;pi++){const [r,c]=lev.pieces[pi].pos;for(const [d,[dr,dc]] of Object.entries(dirs)){const nr=r+dr,nc=c+dc,door=(lev.doors||[]).find(x=>x[0]===nr&&x[1]===nc);if(door)return {L,pi,d,group:door[2]}}}}return null});assert(doorCase,'no adjacent closed-door case found');await settleGame(p,doorCase.L);await p.evaluate(x=>{selected=x.pi},doorCase);await p.evaluate(d=>moveSelected(d),doorCase.d);await p.waitForTimeout(70);const blocked=await p.evaluate(()=>({blocked:document.querySelectorAll('.blocked-feedback').length,linked:document.querySelectorAll('.causal-linked').length,text:document.querySelector('.mechanic-chip-copy')?.textContent}));assert(blocked.blocked>0&&blocked.linked>0&&/door is closed/i.test(blocked.text),`door feedback ${JSON.stringify({doorCase,blocked})}`);
 const swCase=await p.evaluate(()=>{for(let L=301;L<=400;L++){startLevel(L,'campaign');try{window.LatchlingsStoryTheme?.close(false)}catch(_){};for(let pi=0;pi<positions.length;pi++)for(const d of ['U','D','L','R']){const r=simulate(pi,d);if(r?.events?.some(e=>e.type==='switch'))return {L,pi,d}}}return null});assert(swCase,'no switch case found');await settleGame(p,swCase.L);await p.evaluate(x=>{selected=x.pi},swCase);await p.evaluate(d=>moveSelected(d),swCase.d);await p.waitForTimeout(340);const linked=await p.evaluate(()=>({n:document.querySelectorAll('.causal-linked').length,text:document.querySelector('.mechanic-chip-copy')?.textContent}));assert(linked.n>=2&&/linked door/i.test(linked.text),`switch causality ${JSON.stringify({swCase,linked})}`);
 await settleGame(p,1);const first=await p.evaluate(()=>LEVELS[0].solution[0]);await p.evaluate(x=>{selected=x[0];return moveSelected(x[1])},first);await p.waitForTimeout(340);const arrival=await p.locator('.arrival-ack').count();assert(arrival>0,`arrival acknowledgement missing count=${arrival}`);await p.evaluate(()=>rulesModal());assert((await p.locator('#modal').innerText()).includes('3 stars at the Perfect route'),'star criteria missing');results.feedback={doorCase,blocked,swCase,linked,arrival};await shot(p,'gameplay-causality');check('mechanic cause/effect + arrival + star criteria',results.feedback);await ctx.close();
}

// Keyboard focus contracts for modal, Story Card, and cinematic.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844}});const p=await gotoPage(ctx,'focus');await settleGame(p,2);await p.focus('#pauseBtn');await p.click('#pauseBtn');await p.waitForTimeout(50);const m1=await p.evaluate(()=>({inside:document.getElementById('modal').contains(document.activeElement),id:document.activeElement.id}));assert(m1.inside,'modal did not receive focus');await p.press('body','Escape');await p.waitForTimeout(50);assert(await p.evaluate(()=>document.activeElement.id)==='pauseBtn','modal did not restore focus');await p.focus('#storyCardBtn');await p.click('#storyCardBtn');await p.waitForTimeout(50);assert(await p.evaluate(()=>document.getElementById('storyCardPanel').contains(document.activeElement)),'story card did not receive focus');await p.press('body','Escape');await p.waitForTimeout(50);assert(await p.evaluate(()=>document.activeElement.id)==='storyCardBtn','story card did not restore focus');await p.focus('#pauseBtn');await p.evaluate(()=>window.LatchlingsCinematics.show('opening',{markSeen:false}));await p.waitForTimeout(70);assert(await p.evaluate(()=>document.activeElement.id)==='cinematicNext','cinematic did not focus Continue');await p.press('#cinematicNext','Tab');assert(await p.evaluate(()=>document.activeElement.id)==='cinematicSkip','cinematic Tab did not wrap');await p.evaluate(()=>window.LatchlingsCinematics.finish(true));await p.waitForTimeout(50);assert(await p.evaluate(()=>document.activeElement.id)==='pauseBtn','cinematic did not restore focus');results.focus={modal:m1,ok:true};check('dialog focus entry/trap/restore','modal + story card + cinematic');await ctx.close();
}

// Settings persistence and sound interruption hooks.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844}});const p=await gotoPage(ctx,'audio');await p.evaluate(()=>settingsModal());await p.click('#musicToggleBtn');await p.click('#sfxToggleBtn');const off=await p.evaluate(()=>({music:localStorage.getItem('latchlings_music_enabled_v1'),sfx:localStorage.getItem('latchlings_sfx_enabled_v1'),modal:document.body.classList.contains('modal-open')}));assert(off.music==='false'&&off.sfx==='false'&&off.modal,'audio settings did not persist off');await p.click('#settingsClose');await p.evaluate(()=>settingsModal());assert((await p.locator('#musicToggleBtn').innerText()).includes('Off')&&(await p.locator('#sfxToggleBtn').innerText()).includes('Off'),'audio toggles did not reopen persisted');await p.click('#musicToggleBtn');await p.click('#sfxToggleBtn');await p.click('#settingsClose');await p.evaluate(()=>window.LatchlingsCinematics.show('opening',{markSeen:false}));assert(await p.evaluate(()=>document.body.classList.contains('cinematic-open')),'cinematic duck hook missing');await p.evaluate(()=>window.LatchlingsCinematics.finish(true));results.audio=off;check('audio toggle persistence + modal/cinematic interruption hooks',off);await ctx.close();
}

// Additional device/screen geometry, including tablet and explicit landscape behavior.
for(const viewport of [{width:360,height:800},{width:430,height:932},{width:768,height:1024},{width:844,height:390}]){
 const ctx=await contextFor(chromiumBrowser,{viewport,unlocked:351,stars:starsBefore(351)});const p=await gotoPage(ctx,`viewport-${viewport.width}`);const row={viewport};await basicBounds(p,`home ${viewport.width}x${viewport.height}`);await p.evaluate(()=>openStoryScreen());row.story=await basicBounds(p,`story ${viewport.width}x${viewport.height}`);await p.evaluate(()=>{screen('levels');chapterView=7;rangeView=4;renderChapter()});row.atlas=await basicBounds(p,`atlas ${viewport.width}x${viewport.height}`);await settleGame(p,341);row.game=await basicBounds(p,`game ${viewport.width}x${viewport.height}`);await p.evaluate(()=>window.LatchlingsCinematics.show('homeward',{markSeen:false}));await p.waitForTimeout(80);row.cin=await basicBounds(p,`cinematic ${viewport.width}x${viewport.height}`);const nav=await p.evaluate(()=>{const n=document.getElementById('cinematicNext').getBoundingClientRect(),s=document.getElementById('cinematicSkip').getBoundingClientRect();return {nextBottom:n.bottom,skipBottom:s.bottom,nextH:n.height,skipH:s.height}});assert(nav.nextBottom<=viewport.height+1&&nav.skipBottom<=viewport.height+1&&nav.nextH>=44&&nav.skipH>=44,`cinematic viewport nav ${JSON.stringify({viewport,nav})}`);await p.evaluate(()=>window.LatchlingsCinematics.finish(true));await p.evaluate(()=>screen('complete'));await p.waitForTimeout(180);row.ending=await basicBounds(p,`ending ${viewport.width}x${viewport.height}`);results.viewports.push(row);if(viewport.width===360||viewport.height<500)await shot(p,`viewport-${viewport.width}x${viewport.height}`);await ctx.close();
}

// Daily/replay/campaign isolation.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844},unlocked:100,stars:starsBefore(100)});const p=await gotoPage(ctx,'isolation');const before=await p.evaluate(()=>({progress:localStorage.getItem('latchlings_campaign400_progress_v1'),seen:localStorage.getItem('latchlings_cinematics_seen_v1')}));await settleGame(p,366,'daily');const daily=await p.evaluate(()=>({slice:document.getElementById('game').dataset.visualSlice||'',mode:document.body.dataset.playMode,storyBtn:document.getElementById('storyCardBtn').hidden}));assert(daily.mode==='daily'&&daily.slice===''&&daily.storyBtn,'Daily campaign contamination');await p.evaluate(()=>window.LatchlingsCinematics.show('opening',{markSeen:false}));await p.waitForTimeout(30);await p.evaluate(()=>window.LatchlingsCinematics.finish(true));const after=await p.evaluate(()=>({progress:localStorage.getItem('latchlings_campaign400_progress_v1'),seen:localStorage.getItem('latchlings_cinematics_seen_v1')}));assert(before.progress===after.progress&&before.seen===after.seen,`isolation mutation ${JSON.stringify({before,after})}`);check('Daily + replay isolation',{daily});await ctx.close();
}

// Browser-addressable performance and loading measurements, not a substitute for physical low-end-device certification.
{
 const ctx=await contextFor(chromiumBrowser,{viewport:{width:390,height:844},prefs:{motion:'system',textSize:'normal'}});const p=await gotoPage(ctx,'performance');await settleGame(p,400);const perf=await p.evaluate(()=>new Promise(resolve=>{const gaps=[],start=performance.now();let last=start,count=0;function tick(t){gaps.push(t-last);last=t;if(++count<90)requestAnimationFrame(tick);else{const sorted=[...gaps].sort((a,b)=>a-b),resources=performance.getEntriesByType('resource');resolve({frames:gaps.length,median:sorted[Math.floor(sorted.length*.5)],p95:sorted[Math.floor(sorted.length*.95)],max:Math.max(...gaps),resources:resources.length,resourceDuration:resources.reduce((a,x)=>a+x.duration,0),heap:performance.memory?performance.memory.usedJSHeapSize:null})}}requestAnimationFrame(tick)}));assert(perf.p95<80,`hosted Chromium frame pacing severe ${JSON.stringify(perf)}`);results.performance=perf;check('browser frame/loading measurement',perf);await ctx.close();
}

// WebKit-engine smoke at both phone sizes. This is explicitly not genuine iOS hardware certification.
const webkitBrowser=await webkit.launch({headless:true});
for(const viewport of [{width:390,height:844},{width:320,height:568}]){const ctx=await contextFor(webkitBrowser,{viewport,unlocked:400,stars:starsBefore(400)});const p=await gotoPage(ctx,`webkit-${viewport.width}`);await settleGame(p,1);await basicBounds(p,`WebKit game ${viewport.width}`);await p.evaluate(()=>openStoryScreen());await basicBounds(p,`WebKit story ${viewport.width}`);await p.evaluate(()=>window.LatchlingsCinematics.show('opening',{markSeen:false}));await p.waitForTimeout(120);const cin=await p.evaluate(()=>({next:document.getElementById('cinematicNext').getBoundingClientRect().bottom,skip:document.getElementById('cinematicSkip').getBoundingClientRect().bottom,label:document.getElementById('cinematicStage').getAttribute('aria-label')}));assert(cin.next<=viewport.height+1&&cin.skip<=viewport.height+1&&cin.label,'WebKit cinematic failure');await p.evaluate(()=>window.LatchlingsCinematics.finish(true));await p.evaluate(()=>screen('complete'));await p.waitForTimeout(200);const ending=await p.evaluate(()=>({frame:!!document.getElementById('endingHomeFrame').contentDocument?.body?.classList.contains('ending-embed'),overflow:document.documentElement.scrollWidth-innerWidth}));assert(ending.frame&&ending.overflow<=1,`WebKit ending ${JSON.stringify(ending)}`);results.webkit.push({viewport,cin,ending});check(`WebKit engine smoke ${viewport.width}x${viewport.height}`,{cin,ending});await ctx.close()}await webkitBrowser.close();

// Final error gate.
assert(results.errors.length===0,`browser/runtime errors: ${JSON.stringify(results.errors.slice(0,30))}`);
fs.writeFileSync(`${OUT}/full-audit-results.json`,JSON.stringify(results,null,2));
console.log('FULL_ASTRA_AUDIT_BROWSER_ACCEPTANCE_PASSED');
await chromiumBrowser.close();
